(()=>{'use strict';
const CARDS={
armoredshrimp:{n:'呪鱗の守り',i:'🛡️',c:1,b:9,curseBlock:3,curseCap:Infinity,unlock:1,upgrade:{b:3},t:'9ブロック。戦闘中の呪い1枚につき追加3ブロック。',upgradeText:'12ブロック。戦闘中の呪い1枚につき追加3ブロック。',g:'呪い・防御'},
sunfishcalm:{n:'供物の選別',i:'🐚',c:1,dr:2,choice:'cycle',cycleDraw:-1,u:1,unlock:3,upgrade:{dr:1},t:'カードを2枚引き、手札を1枚捨てる。',upgradeText:'カードを3枚引き、手札を1枚捨てる。',g:'アンコモン・手札交換'},
lanternpact:{n:'深海との共生',i:'🏮',c:2,p:0,seedCurse:0,choice:'playDiscarded',u:1,unlock:3,upgrade:{c:-1},t:'手札を1枚選んで捨て、そのカードの効果をコストなしで発動する。',g:'捨て札・共生'},
gobysweep:{n:'呪牙の一刺し',i:'🦈',c:1,d:9,curseDamage:3,curseCap:Infinity,unlock:5,upgrade:{d:3},t:'9ダメージ。戦闘中の呪い1枚につき追加3ダメージ。',upgradeText:'12ダメージ。戦闘中の呪い1枚につき追加3ダメージ。',g:'呪い・攻撃'},
cleanerflow:{n:'脱皮する海流',i:'🌊',c:1,b:4,choice:'cycle',u:1,unlock:5,upgrade:{b:3},t:'4ブロック。手札1枚を選んで捨て、2枚引く。',g:'手札交換'},
nautilusreturn:{n:'サルベージ',i:'⚓',c:2,choice:'recoverExhaust',exhaust:1,r:1,unlock:7,upgrade:{exhaust:-1},t:'廃棄札からカード1枚を選び、手札に戻す。使い切り。',upgradeText:'廃棄札からカード1枚を選び、手札に戻す。',g:'廃棄札回収'},
voidtribute:{n:'反転術式',i:'🌀',c:2,d:0,curseDamage:0,curseCap:0,handCursePoison:0,curseInvert:1,exhaust:1,a:1,unlock:7,upgrade:{c:-1},t:'この戦闘中、ターン終了時の呪いダメージを同じ値のHP回復に反転する。使い切り。',g:'呪い・反転'},
flyingbreath:{n:'重荷を流す',i:'🐟',c:1,b:5,choice:'exhaustHand',randomExhaustHand:1,unlock:9,upgrade:{b:2,randomExhaustHand:-1},t:'5ブロック。ランダムな手札1枚を廃棄。',upgradeText:'7ブロック。手札1枚を選んで廃棄。',g:'廃棄・防御'}
};
window.ABYSS_ASCENSION_CARDS=CARDS;
const base=k=>String(k||'').replace(/~\d+$/,'').replace(/[+*]+$/,'');
const rarity=c=>c.a?'abyss':c.r?'rare':c.u?'uncommon':'common';
window.isAbyssCardUnlocked=k=>!CARDS[base(k)]||(window.getAbyssAscensionMeta?.().clears||[]).includes(CARDS[base(k)].unlock);
window.getAbyssUnlockCards=rank=>Object.keys(CARDS).filter(k=>CARDS[k].unlock===rank);
window.extendAbyssCardPool=(pool,tier)=>[...new Set([...pool,...Object.keys(CARDS).filter(k=>window.isAbyssCardUnlocked(k)&&(tier==='standard'?['common','uncommon'].includes(rarity(CARDS[k])):rarity(CARDS[k])===tier))])];
window.getAbyssCardUnlockMarkup=keys=>keys?.length?'<div class="card-unlock-reward"><b>新しいカードが解放されました</b><p>次の潜航から報酬・ショップなどに登場します。</p><div class="card-unlock-list unified-card-grid">'+keys.map(k=>window.renderAbyssCardView?.(k,{hideTag:true})||'').join('')+'</div></div>':'';
const isCurse=k=>window.getAbyssCardData?.(k)?.g==='呪い';
window.countAbyssCurses=g=>[...(g.draw||[]),...(g.hand||[]),...(g.discard||[])].filter(isCurse).length;
window.prepareAbyssUnlockCard=(c,g)=>{
 const count=Math.min(c.curseCap||0,window.countAbyssCurses(g));
 if(c.curseBlock)c.b+=count*c.curseBlock;
 if(c.curseDamage)c.d+=count*c.curseDamage;
 if(c.handCursePoison)c.p=Math.min(3,(g.hand||[]).filter(isCurse).length);
 if(c.seedCurse&&!g.curseSeeded){g.curseSeeded=true;g.discard.push('abysscurse')}
};
const recovering=kind=>kind.startsWith('recover');
const recoverSource=(g,kind)=>kind==='recoverExhaust'?(g.exhausted||[]):g.discard;
function options(g){const pending=g.cardChoice;if(!pending)return[];const kind=pending.kind,from=kind==='dredge'||kind==='sonar'||kind==='tutorDraw'?g.draw:kind==='topDiscard'||recovering(kind)?recoverSource(g,kind):g.hand;if(kind==='dredge')return g.hand.length>=(window.abyssHandLimit?.(g)||8)?[]:from.map((k,index)=>({k,index})).slice(-3);if(kind==='sonar')return from.map((k,index)=>({k,index})).slice(-(pending.choiceCount||3));if((recovering(kind)||kind==='tutorDraw')&&g.hand.length>=(window.abyssHandLimit?.(g)||8))return[];return from.map((k,index)=>({k,index})).filter(({k})=>{const c=window.getAbyssIntrinsicCardStats?.(k)||{};if(kind==='curseHand')return !isCurse(k);if(kind==='playDiscarded'&&base(k)==='lanternpact')return false;if(kind==='recoverCurse')return isCurse(k);return kind!=='recoverSmall'||c.c<=1})}
function settleChoiceCard(g,pending){if(!pending.key)return;if(pending.exhaustKey)(g.exhausted||=[]).push(pending.key);else g.discard.push(pending.key)}
function closeChoice(g){const pending=g.cardChoice;if(!pending)return;if(pending.secondaryKey)g.discard.push(pending.secondaryKey);if(pending.afterChoice){g.cardChoice=pending.afterChoice;window.abyssSave?.();window.resumeAbyssCardChoice?.();window.debugAbyssRefresh?.();return}if(pending.parentKey)g.discard.push(pending.parentKey);if(pending.repeatChoice>0){g.cardChoice={kind:pending.kind,key:pending.key,exhaustKey:pending.exhaustKey,repeatChoice:pending.repeatChoice-1,choiceCount:pending.choiceCount||0,choiceDraw:pending.choiceDraw||0};window.abyssSave?.();window.resumeAbyssCardChoice?.();window.debugAbyssRefresh?.();return}settleChoiceCard(g,pending);delete g.cardChoice;g.cardBusy=false;g.cardBusyAt=0;document.getElementById('curseCardChoice')?.classList.remove('on');window.abyssSave?.();window.debugAbyssRefresh?.()}
window.cancelAbyssCardChoice=closeChoice;
window.selectAbyssCardChoice=index=>{const g=window.getAbyssGame?.(),pending=g?.cardChoice;if(!pending)return;const chosen=options(g).find(o=>o.index===index);if(index!==null&&!chosen)return;if(chosen){const kind=pending.kind,curse=isCurse(chosen.k);if(kind==='curseHand'){g.hand[chosen.index]='abysscurse'}else if(kind==='dredge'){const top=g.draw.splice(Math.max(0,g.draw.length-3));const selected=top.splice(chosen.index-g.draw.length,1)[0];g.hand.push(window.abyssRandomizeDrawCost?.(selected)||selected);g.discard.push(...top);if(top.length)window.tacticalCardMoved?.(g,'discard')}else if(kind==='tutorDraw'){g.draw.splice(chosen.index,1);g.hand.push(chosen.k)}else if(kind==='topDiscard'){g.discard.splice(chosen.index,1);g.draw.push(chosen.k);window.tacticalCardMoved?.(g,'draw')}else if(kind==='sonar'){const start=Math.max(0,g.draw.length-(pending.choiceCount||3)),top=g.draw.splice(start),selected=top.splice(chosen.index-start,1)[0];g.discard.push(...top);if(selected!=null)g.draw.push(selected);if(top.length)window.tacticalCardMoved?.(g,'discard')}else if(recovering(kind)){const source=recoverSource(g,kind);source.splice(chosen.index,1);g.hand.push(chosen.k);if(kind==='recoverCurse')window.drawAbyssCards?.(2)}else if(kind==='playDiscarded'){g.hand.splice(chosen.index,1);window.tacticalCardMoved?.(g,'discard');const replay=window.getAbyssCardStats?.(chosen.k);window.resolveAbyssCardEffect?.(replay,chosen.k);if(replay?.choice){const after=pending.repeatChoice>0?{kind:'playDiscarded',key:pending.key,exhaustKey:pending.exhaustKey,repeatChoice:pending.repeatChoice-1}:null;g.cardChoice={kind:replay.choice,key:null,secondaryKey:chosen.k,afterChoice:after,parentKey:after?null:pending.key};window.abyssSave?.();window.resumeAbyssCardChoice?.();return}g.discard.push(chosen.k)}else{g.hand.splice(chosen.index,1);if(kind==='cycle'){g.discard.push(chosen.k);if(pending.choiceDraw>=0)window.drawAbyssCards?.(pending.choiceDraw||2);window.tacticalCardMoved?.(g,'discard')}else{(g.exhausted||=[]).push(chosen.k);window.tacticalCardMoved?.(g,'exhaust');if(kind==='offering'){if(curse){g.block+=6;if(g.runStats)g.runStats.blockGained+=6}else window.drawAbyssCards?.(String(pending.key).includes('+')?2:1)}if(kind==='shed'&&curse&&!g.curseEnergyUsed){g.curseEnergyUsed=true;g.energy+=1}if(kind==='voidExhaust'&&g.hand.length<(window.abyssHandLimit?.(g)||8))g.hand.push('abysscurse')}}}closeChoice(g)};
window.resumeAbyssCardChoice=()=>{const g=window.getAbyssGame?.();if(!g?.cardChoice)return;if(!g.enemy||g.enemy.hp<=0){closeChoice(g);return}let modal=document.getElementById('curseCardChoice');if(!modal){modal=document.createElement('div');modal.id='curseCardChoice';modal.className='modal';document.body.appendChild(modal)}const list=options(g),kind=g.cardChoice.kind;modal.innerHTML='<div class="panel modal-shell"><header class="modal-shell-head"><div><h2>'+({curseHand:'呪いに変換する手札を選ぶ',dredge:'山札の上3枚から1枚選ぶ',sonar:'山札の上から戻す1枚を選ぶ',tutorDraw:'山札から手札に加えるカードを選ぶ',topDiscard:'山札の上に置く捨て札を選ぶ',playDiscarded:'捨てて発動するカードを選ぶ',recoverSmall:'捨て札から1枚回収',recoverAny:'捨て札から1枚回収',recoverExhaust:'廃棄札から1枚回収',recoverCurse:'呪いを1枚回収',cycle:'手札を1枚捨てる',offering:'手札を1枚廃棄',shed:'手札を1枚廃棄',exhaustHand:'手札を1枚廃棄',voidExhaust:'手札を1枚廃棄'}[kind])+'</h2><p>'+(kind==='curseHand'?'選んだ手札は、この戦闘中だけ呪いになります。戦闘終了後は元のカードに戻ります。':kind==='playDiscarded'?'選んだカードは捨て札へ送り、コストなしで効果を発動します。':kind==='sonar'?'選んだカードを山札の一番上へ戻し、残りは捨て札へ送ります。':kind==='tutorDraw'?'選んだ山札を手札へ加えます。手札の上限は'+(window.abyssHandLimit?.(g)||8)+'枚です。':kind==='topDiscard'?'選んだ捨て札を山札の一番上に置きます。':kind==='cycle'?'カードを引きました。手札から捨てるカードを1枚選びます。':kind==='recoverExhaust'?'選んだ廃棄札を手札へ戻します。手札の上限は'+(window.abyssHandLimit?.(g)||8)+'枚です。':'廃棄したカードは、この戦闘中だけ戻りません。手札の上限は'+(window.abyssHandLimit?.(g)||8)+'枚です。')+'</p></div></header><div class="modal-shell-body curse-choice-list mark-card-list">'+(list.length?list.map(({k,index})=>`<button type="button" class="choice mark-card unified-card-choice" data-choice-index="${index}">${window.renderAbyssCardView?.(k)||''}</button>`).join(''):'<p>選べるカードがありません。</p>')+'</div><footer class="modal-shell-foot">'+(list.length?'<button type="button" class="btn gold" data-choice-confirm disabled>決定</button>':'<button type="button" data-choice-skip>続ける</button>')+'</footer></div>';let selected=null;const cardBtns=modal.querySelectorAll('[data-choice-index]'),confirmBtn=modal.querySelector('[data-choice-confirm]');cardBtns.forEach(b=>b.onclick=()=>{selected=+b.dataset.choiceIndex;cardBtns.forEach(x=>x.classList.toggle('selected',x===b));if(confirmBtn)confirmBtn.disabled=false});if(confirmBtn)confirmBtn.onclick=()=>{if(selected!==null)window.selectAbyssCardChoice(selected)};modal.querySelector('[data-choice-skip]')?.addEventListener('click',()=>window.selectAbyssCardChoice(null));modal.classList.add('on');window.applyFuri?.(modal)};
window.openAbyssCardChoice=(c,g,k,repeatChoice=0)=>{if((c.choice==='dredge'||c.choice==='sonar')&&!g.draw.length){g.draw=g.discard.sort(()=>Math.random()-.5);g.discard=[]}const picks=Math.max(1,c.choicePicks||1),repeats=(repeatChoice+1)*picks-1;g.cardChoice={kind:c.choice,key:k,exhaustKey:!!c.exhaust,repeatChoice:repeats,choiceCount:c.sonarCount||0,choiceDraw:c.cycleDraw||0};window.abyssSave?.();window.resumeAbyssCardChoice()};
})();
